   "orig": "Hurricane Simon nears Mexico with 155 mph winds and flooding fears",
   "lead": "L'occhio dell'uragano Simon si trovava domenica mattina presto appena al largo della costa pacifica del Messico, con venti sostenuti di circa 250 km/h, ed era previsto che si spostasse sulla terraferma più avanti nella giornata come tempesta di straordinaria potenza, con il rischio di forti inondazioni. Lo riferisce NPR.",
