   "titolo": "Trump annuncia una 'tregua energetica' tra Russia e Ucraina",
   "orig": "Trump meldet \"Energie-Waffenruhe\" zwischen Russland und Ukraine",
   "lead": "Il presidente statunitense Donald Trump ha dichiarato che Russia e Ucraina hanno raggiunto un accordo per una 'tregua energetica', in vigore con effetto immediato, secondo quanto scritto sulla sua piattaforma Truth Social. Né Kiev né Mosca hanno finora confermato l'intesa. Trump ha inoltre affermato che l'Ucraina avrebbe bisogno di un nuovo capo di stato, mentre il presidente ucraino Zelensky si è detto pronto ad accettare un simile accordo.",
