    "Le 'tregue energetiche' discusse nel conflitto russo-ucraino riguardano la sospensione reciproca degli attacchi contro le infrastrutture energetiche, spesso colpite da entrambe le parti durante l'inverno per fiaccare la popolazione civile e la rete elettrica."
