   "titolo": "Come le alghe di uno stagno hanno portato a un Nobel e a nuovi strumenti per studiare il cervello",
   "orig": "THE CONVERSATION: How pond algae led to a Nobel and new ways to study the brain",
   "lead": "Tre ricercatori sono stati premiati con il Nobel per la fisiologia o la medicina per aver scoperto nuovi modi di controllare le cellule nervose, una ricerca partita da uno studio sulle alghe degli stagni e da una domanda scientifica semplice. Lo riferisce Daily Maverick.",
