   "titolo": "La corsa alla pensione anticipata: il movimento FIRE conquista Millennial e Gen Z",
   "orig": "Cursa pentru pensionarea „anticipată”. Fenomenul FIRE prinde Milenialii și Gen Z. Cum funcționează și care sunt riscurile",
   "lead": "Il movimento Financial Independence, Retire Early (FIRE), che punta all'indipendenza finanziaria e al ritiro anticipato dal lavoro, sta guadagnando popolarità tra i giovani, complice l'inflazione elevata, i tassi d'interesse più alti e il costo della vita in crescita. Il meccanismo si basa su una drastica riduzione delle spese quotidiane per accumulare risorse e andare in pensione prima del tempo. Lo riferisce HotNews.",
   "more": [
    "Il FIRE è un movimento nato negli Stati Uniti negli anni 2010, che propone stili di vita molto parsimoniosi e investimenti aggressivi per raggiungere l'indipendenza economica in età relativamente giovane, rispetto all'età pensionabile tradizionale."
   ],
