   "lead": "Il governatore del Khyber Pakhtunkhwa, Faisal Karim Kundi, ha presieduto domenica la prima riunione del Consiglio consultivo della provincia, istituito dal governo federale dopo l'imposizione dello stato di emergenza e del governo del governatore nella regione. Kundi ha dichiarato che ci sarà 'tolleranza zero' sulla corruzione e che i membri avranno pochi giorni per familiarizzare con i loro incarichi prima di ricevere i briefing sui rispettivi portafogli. Lo riferisce Dawn.",
