   "lead": "I due partiti ultraortodossi israeliani Shas e Giudaismo Unito della Torah hanno firmato un accordo sui 'voti in eccedenza' in vista delle elezioni israeliane, che permetterà al partito con più voti di ottenere un seggio supplementare. In una dichiarazione congiunta, Arye Dery di Shas e Yakov Asher di Giudaismo Unito della Torah hanno definito l'intesa un segno di 'continua cooperazione tra le fazioni'. Lo riferisce Haaretz.",
