   "lead": "Il governo del Gabon, con sede a Libreville, sta considerando l'emissione di un nuovo eurobond per un valore di 332 miliardi di franchi CFA. Nell'operazione sarebbe coinvolta BofA Securities, divisione di Bank of America con sede in North Carolina, mentre il Servizio economico regionale di Yaoundé segue il dossier. Lo riferisce Gabonactu.",
