   "titolo": "Revisione su autismo, ADHD e salute mentale: cosa cambia per il sistema sanitario britannico",
   "orig": "Autism, ADHD and mental health review: What you need to know",
   "lead": "Una revisione governativa sull'autismo, l'ADHD e la salute mentale nel Regno Unito avverte che il paese rischia di passare da un'epoca di sotto-diagnosi a una di sovra-diagnosi, in particolare tra i più giovani. Il rapporto, guidato dallo psicologo clinico Peter Fonagy, indica la necessità di un cambiamento radicale nel sistema di supporto del Servizio sanitario nazionale (NHS), finora troppo legato all'etichetta diagnostica, con ricadute su welfare, istruzione e politiche del lavoro.",
   "more": [
    "L'ADHD (disturbo da deficit di attenzione e iperattività) e l'autismo sono condizioni dello sviluppo neurologico; negli ultimi anni le diagnosi sono aumentate notevolmente nel Regno Unito, generando un dibattito su accuratezza diagnostica e capacità dei servizi sanitari di rispondere alla domanda crescente."
   ],
