   "sez": "salute",
   "titolo": "Pressioni invernali sul NHS: liste d'attesa in crescita e livelli di influenza già alti",
   "orig": "'Ominous signs' of winter pressures as NHS waiting list grows",
   "lead": "Il Servizio sanitario nazionale britannico mostra già i primi segnali di difficoltà invernale, con un aumento dei tempi di attesa per gli interventi chirurgici programmati. Le autorità sanitarie britanniche, tramite la UK Health Security Agency, segnalano che i livelli di influenza sono più alti rispetto agli ultimi quattro anni in questo periodo dell'anno, con conseguenze che si fanno già sentire negli ospedali inglesi.",
   "more": [
    "Ogni autunno il NHS affronta il cosiddetto periodo delle \"pressioni invernali\", quando l'aumento di casi di influenza, Covid e altre malattie respiratorie si somma alla domanda ordinaria, mettendo sotto stress pronto soccorso e liste d'attesa per gli interventi non urgenti."
   ],
