   "id": "zd51c060c",
   "sez": "mondo",
   "titolo": "L'aeroporto di Riad, vetrina del sogno di bin Salman, colpito dalla guerra",
   "orig": "Riad, la vetrina del sogno di bin Salman toccata dalla guerra",
   "lead": "L'aeroporto King Khalid di Riad, dove almeno 12 persone sono morte in seguito a un attacco degli Houthi yemeniti, rappresenta la porta d'ingresso di una metropoli nel deserto lanciata verso la modernità secondo il progetto del principe ereditario saudita Mohammed bin Salman. L'attacco ha colpito simbolicamente uno dei luoghi chiave dell'ambizioso piano di trasformazione urbana e economica voluto dal governo saudita.",
   "more": [
    "Riad è il centro del piano di modernizzazione \"Vision 2030\" promosso da Mohammed bin Salman, che punta a diversificare l'economia saudita oltre il petrolio attraverso grandi investimenti infrastrutturali, turistici e tecnologici. Gli Houthi, movimento ribelle yemenita appoggiato dall'Iran, sono in conflitto con la coalizione guidata dall'Arabia Saudita da anni."
   ],
