   "id": "z892dc139",
   "sez": "italia",
   "titolo": "ANIEF: servono interventi strutturali sugli stipendi di docenti e ATA, non bonus da 100 euro",
   "orig": "Stipendi docenti e ATA, Pacifico (ANIEF): “Senza indennità e sconti fiscali sui trasporti, servono interventi strutturali non bonus da 100 euro”",
   "lead": "Il sindacalista Marcello Pacifico, segretario di ANIEF, chiede di alleggerire la pressione fiscale sul ceto medio-basso e garantire un salario più equo per i lavoratori della scuola e del pubblico impiego a partire dal 2027, criticando le misure limitate come i bonus trasporto. In parallelo, dal 2027 cambia anche il sistema dei bonus per il trasporto pubblico: non più agevolazioni per tutti, ma voucher per le famiglie fino a 20mila euro di ISEE, con importi da 100, 200 e 400 euro variabili in base al reddito familiare e alla distanza casa-lavoro.",
   "more": [
    "ANIEF è un sindacato della scuola italiana che si occupa delle condizioni economiche e contrattuali di docenti e personale ATA (amministrativo, tecnico e ausiliario); le indennità di trasporto e gli sconti fiscali sono strumenti usati periodicamente dal governo per sostenere il reddito dei lavoratori pubblici."
   ],
