   "id": "z76bfe7f0",
   "sez": "italia",
   "titolo": "Legge 104, dal 2027 aumentano i massimali per il congedo straordinario",
   "orig": "Legge 104, nuovi importi massimi nel 2027 per il congedo straordinario: come aumentano per la rivalutazione, quanto si può ricevere",
   "lead": "Nel 2027 sono previsti nuovi importi massimi per il congedo straordinario legato alla Legge 104, la normativa che consente ai lavoratori dipendenti di assentarsi dal lavoro per assistere familiari con disabilità grave. L'aumento deriva dalla rivalutazione periodica dei massimali economici previsti dalla legge. Collegata a questa novità, anche l'assegno unico di ottobre 2026 verrà pagato il 21 e 22 del mese secondo le date fissate dall'Inps, con la rivalutazione degli importi che scatterà sempre dal 2027.",
   "more": [
    "La Legge 104 del 1992 è la normativa italiana che tutela le persone con disabilità e i loro familiari, prevedendo tra l'altro permessi e congedi lavorativi retribuiti; i massimali economici di questi congedi vengono periodicamente rivalutati in base all'inflazione."
   ],
