   "id": "z6ce71112",
   "sez": "mondo",
   "titolo": "Tashkent acquisterà 14 nuovi treni metro da cinque vagoni",
   "orig": "Tashkent metro plans to buy 14 new five-car trains.",
   "lead": "La città di Tashkent, capitale dell'Uzbekistan, ha approvato un piano per l'acquisto di 14 nuovi treni per la metropolitana, composti complessivamente da 70 vagoni, con costi di fornitura stimati tra 118,3 e 279,1 milioni di dollari in base al produttore scelto. Le consegne sono previste in tre fasi, con l'ultimo lotto atteso entro il 1° novembre 2027. Attualmente la metro di Tashkent utilizza treni da quattro vagoni; sono stati considerati anche convogli da sei vagoni, ma le banchine delle stazioni risultano troppo corte per ospitarli.",
   "more": [
    "La metropolitana di Tashkent, aperta nel 1977, è uno dei pochi sistemi di trasporto sotterraneo dell'Asia centrale ed è stata oggetto negli ultimi anni di piani di modernizzazione per rispondere alla crescita della domanda di trasporto pubblico nella capitale uzbeka."
   ],
