   "id": "z96e56c40",
   "sez": "mondo",
   "titolo": "Il presidente uzbeko propone di accelerare un'alleanza dell'Asia centrale sui minerali critici",
   "orig": "President of Uzbekistan proposes accelerating creation of Central Asian critical minerals alliance",
   "lead": "Il presidente dell'Uzbekistan Shavkat Mirziyoyev ha proposto di accelerare la creazione di un'alleanza tra i paesi dell'Asia centrale sui minerali critici e lo sviluppo di una mappa digitale unificata delle loro riserve. Mirziyoyev ha inoltre chiesto una collaborazione congiunta per sviluppare l'energia a basse emissioni di carbonio nella regione.",
   "more": [
    "I minerali critici (come litio, cobalto o terre rare) sono materie prime essenziali per tecnologie come batterie e pannelli solari; i paesi dell'Asia centrale, ricchi di risorse minerarie, puntano a coordinarsi per aumentare il proprio peso sui mercati globali."
   ],
