   "id": "z06e6c94d",
   "sez": "mondo",
   "titolo": "Un responsabile del Programma alimentare mondiale chiede di non abbandonare i rifugiati",
   "orig": "Interview avec Jean de Lestrange : « N’oubliez pas les réfugiés, n’oubliez pas de les assister, aidez-les à retrouver leur pleine dignité ! »",
   "lead": "Jean de Lestrange, responsabile dei partenariati per il Programma alimentare mondiale (PAM), ha lanciato un appello a non dimenticare i rifugiati e a continuare ad assisterli per restituire loro piena dignità, durante una visita il 7 ottobre 2026 al campo dei rifugiati congolesi di Busuma, in provincia di Buhumuza. L'intervista arriva dopo che il PAM aveva avvertito a luglio 2026 di un possibile arresto dell'assistenza alimentare ai rifugiati a partire da ottobre. Nel frattempo, nel campo di Kakuma, in Kenya, i rifugiati denunciano la propria vulnerabilità davanti all'arrivo di forti intemperie annunciate.",
   "more": [
    "Il Programma alimentare mondiale (PAM) è l'agenzia delle Nazioni Unite che fornisce assistenza alimentare alle popolazioni in difficoltà nel mondo, inclusi i campi per rifugiati; i tagli ai finanziamenti internazionali hanno più volte minacciato la continuità di questi aiuti negli ultimi anni."
   ],
