   "orig": "iciHaïti - Politique : Moïse Jean-Charles rejette les accusations de l'ONU",
   "lead": "Il partito politico haitiano Pitit Dessalines ha annunciato di aver presentato formalmente un ricorso al Segretario generale delle Nazioni Unite e al Gruppo di esperti su Haiti riguardo alle accuse rivolte al proprio leader, l'ex senatore Moïse Jean-Charles, definito dagli esperti ONU il principale beneficiario nel settore del traffico illegale. Jean-Charles rigetta le accuse.",
