   "orig": "In one of the country's most competitive districts, a Democrat tries to keep her seat",
   "lead": "In un distretto congressuale dello stato di Washington tra i più combattuti degli Stati Uniti, la deputata democratica uscente cerca di mantenere il proprio seggio dopo aver suscitato malumori in una parte della base del suo partito. Lo sfidante repubblicano, sostenuto da Trump, deve invece fare i conti con il malcontento generale verso il partito attualmente al potere. Lo riferisce NPR.",
