   "orig": "Cheong Wa Dae says Lee ordered rescue operations for Daegu incident while on golf course",
   "lead": "L'ufficio presidenziale sudcoreano Cheong Wa Dae ha confermato che il presidente Lee Jae Myung stava effettivamente giocando a golf quando ha ordinato le operazioni di soccorso in relazione a un incidente avvenuto a Daegu. La precisazione arriva in risposta a polemiche sulla gestione della vicenda da parte della presidenza. Lo riferisce Yonhap.",
