   "lead": "Il rimpasto di governo del 17 settembre ha portato alla premier giapponese Takaichi Sanae alcune notizie positive sul fronte del sostegno pubblico, ma i suoi indici di gradimento sono rimasti complessivamente invariati. L'attenzione resta concentrata sulle ombre di scandali che la circondano e sulle prospettive delle future scelte politiche del suo governo. Lo riferisce Nippon.com.",
