   "lead": "La campionessa mondiale brasiliana di taekwondo Maria Clara Pacheco, numero uno del ranking mondiale, ha vinto sabato 10 ottobre la terza tappa del Grand Prix Series 2026, disputata a Parigi. Nella categoria fino a 57 chili ha sconfitto in finale la giordana Fadia Khirfan, terza nel ranking, con il punteggio di 2 round a 0. Prima della finale ha superato Kanelya Carabin e l'iraniana vicecampionessa olimpica Nahid Kiyanichandeh. Lo riferisce Agência Brasil.",
