   "orig": "A Trump impersonator and opera singers: CPAC was a spectacle, but the right still can’t agree how to take down Labor",
   "lead": "Alla Conferenza dell'azione politica conservatrice (CPAC) di Brisbane, tra un imitatore di Donald Trump e cantanti d'opera che intonavano l'inno nazionale, i conservatori australiani si sono confrontati senza trovare un accordo sulle preferenze elettorali, mentre si profila il rischio di una terza sconfitta elettorale consecutiva per il partito. Lo riferisce The Guardian.",
