   "orig": "Il Papa e il nodulo polmonare, ecco come si diagnostica e quando si interviene",
   "lead": "Dopo la notizia di un nodulo polmonare riscontrato al Papa, un esperto spiega come si effettua la diagnosi di questo tipo di riscontro clinico e chiarisce che non equivale automaticamente a una diagnosi di tumore. Vengono illustrate le tecniche mininvasive disponibili e i possibili percorsi di cura. Lo riferisce ANSA.",
