   "sez": "salute",
   "titolo": "Allarme svapo tra i giovani: i pediatri propongono screening già dagli 11 anni",
   "orig": "Sigarette, allarme svapo tra i giovani. I pediatri: screening già dagli 11 anni",
   "lead": "Secondo i dati dell'Istituto superiore di sanità, più di uno studente su tre tra i 14 e i 17 anni (il 37,1%, circa 851mila ragazzi) ha utilizzato sigarette elettroniche. Di fronte a questo dato i pediatri propongono di avviare lo screening sull'uso di questi dispositivi già a partire dagli 11 anni. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "Le sigarette elettroniche, o dispositivi per lo svapo, sono strumenti che vaporizzano liquidi spesso contenenti nicotina; il loro uso tra i minori è oggetto di crescente preoccupazione sanitaria per i possibili effetti sulla salute e sul rischio di dipendenza."
   ],
