   "orig": "Ebola: 122 contacts verified, 108 in quarantine as tracing continues",
   "lead": "Le autorità sanitarie stanno continuando a tracciare i contatti dei casi di Ebola: finora sono stati verificati 122 contatti, di cui 108 posti in quarantena, mentre la ricerca dei contatti rimanenti è ancora in corso. È in atto una risposta nazionale coordinata per contenere il virus. Lo riferisce Citizen Digital.",
