   "id": "z4f1a772a",
   "sez": "cultura",
   "titolo": "Il Nobel per la letteratura alla poetessa canadese Anne Carson",
   "orig": "'Bold and inventive' Canadian poet Anne Carson wins Nobel Literature Prize",
   "lead": "L'Accademia svedese ha assegnato il premio Nobel per la letteratura 2026 alla poetessa e saggista canadese Anne Carson, 76 anni. È apprezzata per opere «audaci e inventive», che spesso uniscono poesia, narrativa e studio dei classici, come «Autobiografia del rosso». Scrittori come Margaret Atwood e Édouard Louis hanno festeggiato il premio. Louis racconta di averla scoperta su un autobus, bloccato in una tempesta di neve. Diverse testate suggeriscono da quali libri cominciare a leggerla.",
   "more": [
    "Anne Carson è anche una studiosa di letteratura greca antica e ha tradotto autori classici come Saffo. Nei suoi libri mescola generi diversi: il romanzo in versi, il saggio, l'autobiografia e la poesia."
   ],
