   "sez": "tech",
   "titolo": "Licenziati da OpenAI tre ricercatori della sicurezza: «Abbiamo messo la sicurezza al primo posto»",
   "orig": "Fired OpenAI researchers say they were let go for 'prioritising safety'",
   "lead": "Tre ricercatori che lavoravano alla sicurezza dell'intelligenza artificiale in OpenAI dicono di essere stati licenziati perché avevano «dato priorità alla sicurezza». Si tratta di Mikita Balesni, Tomak Korbak e Jasmine Wang, che si occupavano di far sì che i sistemi di IA facciano ciò che vogliono i loro utilizzatori umani. I tre parlano di circostanze «sospette». L'azienda sostiene invece di averli licenziati perché hanno gestito male informazioni riservate.",
   "more": [
    "OpenAI è l'azienda statunitense che ha creato ChatGPT. Il cosiddetto «allineamento» è il settore di ricerca che cerca di far sì che i sistemi di intelligenza artificiale si comportino secondo le intenzioni e i valori delle persone."
   ],
