   "id": "zedb9e95b",
   "sez": "mondo",
   "titolo": "Come il conflitto tra Houthi e Arabia Saudita tocca l'Africa del Mar Rosso",
   "orig": "How the Houthi-Saudi conflict is affecting countries on Africa's Red Sea coast — and beyond",
   "lead": "Il conflitto tra i ribelli Houthi e l'Arabia Saudita ha conseguenze anche sui Paesi africani che si affacciano sul Mar Rosso. A settembre gli Houthi, sostenuti dall'Iran, hanno conquistato l'isola yemenita di Perim. L'isola si trova nel punto più stretto dello stretto di Bab el-Mandeb, che collega il Mar Rosso al Golfo di Aden. Le forze del governo yemenita cercano di riprendere lo stretto, che è vicino a Gibuti e ad altri Stati africani.",
   "more": [
    "Lo stretto di Bab el-Mandeb separa la penisola arabica dal Corno d'Africa. È una delle rotte marittime più importanti del mondo, perché ci passano le navi tra il Mediterraneo, attraverso il canale di Suez, e l'oceano Indiano."
   ],
