   "titolo": "Giornata mondiale degli insegnanti: in Sudan i docenti chiedono alloggi e sostegno",
   "orig": "World Teachers’ Day: Sudanese educators call for housing and better support",
   "lead": "In occasione della Giornata mondiale degli insegnanti, i docenti del Sudan chiedono un alloggio e più sostegno. La guerra nel Paese sta sconvolgendo il sistema scolastico. Secondo gli insegnanti, gli stipendi bassi e le cattive condizioni di lavoro li stanno mettendo in grande difficoltà. Nelle Filippine, invece, il 2 ottobre la città di San Juan ha festeggiato i suoi insegnanti in una cerimonia con il sindaco Francis Zamora.",
   "more": [
    "La Giornata mondiale degli insegnanti è promossa dall'UNESCO e si celebra ogni anno all'inizio di ottobre. In Sudan la guerra civile ha costretto milioni di persone a lasciare le loro case e ha fatto chiudere molte scuole."
   ],
