   "sez": "mondo",
   "titolo": "Attacchi su Riad e nello Stretto di Hormuz, sale la tensione in Medio Oriente",
   "orig": "Angriffe auf Riad und Straße von Hormus verschärfen Spannungen im Nahen Osten",
   "lead": "La tensione in Medio Oriente torna a crescere dopo una serie di attacchi che hanno colpito la capitale saudita Riad e lo Stretto di Hormuz, uno dei passaggi marittimi più delicati della regione. L'emittente pubblica tedesca Tagesschau collega i due fronti e parla di un aggravamento complessivo della situazione. L'austriaca ORF aggiunge un dettaglio rilevante: è stato l'esercito degli Stati Uniti ad attaccare una petroliera nello Stretto di Hormuz. Questo coinvolgimento diretto di Washington nelle operazioni in mare rende il quadro ancora più instabile e alimenta i timori di un'escalation tra le potenze presenti nell'area.",
   "more": [
    "Lo Stretto di Hormuz collega il Golfo Persico al Golfo di Oman e al mare aperto. Da qui transita una quota molto importante del petrolio esportato dai Paesi del Golfo. Per questo ogni episodio militare nella zona ha ripercussioni immediate sulla sicurezza della navigazione e sui mercati energetici di tutto il mondo."
   ],
