   "titolo": "Due tornado colpiscono Marsala: decine di feriti e una scuola danneggiata",
   "orig": "Dozens injured and buildings damaged as tornadoes hit Sicily",
   "lead": "Venerdì mattina due tornado si sono abbattuti su Marsala, città costiera della Sicilia occidentale. Hanno ferito decine di persone, danneggiato diversi edifici, tra cui una scuola, e ribaltato alcune automobili. I fenomeni sono nati da una forte perturbazione arrivata dal Mediterraneo. Sui social sono circolati numerosi video che mostrano due trombe marine avvicinarsi alla città dal mare, mentre gli abitanti si preparavano all'impatto. Marsala risulta tra le località più colpite dal maltempo. Lo riferisce The Guardian.",
   "more": [
    "Marsala si trova sulla punta occidentale della Sicilia, in provincia di Trapani. È famosa per il vino liquoroso che porta il suo nome e per lo sbarco dei Mille di Garibaldi. Le trombe marine sono vortici che si formano sul mare e che a volte raggiungono la costa."
   ],
