   "titolo": "Australia, un piano nazionale per difendere la fauna dalle volpi",
   "orig": "‘We cannot accept foxes as part of our landscape’: the plan to save Australia’s threatened wildlife",
   "lead": "L'Australia prepara una strategia nazionale contro la volpe rossa europea, una specie invasiva che ogni giorno uccide più di un milione di animali nativi. La bozza riconosce che eliminarla del tutto non è possibile. Indica però le misure per proteggere le specie più a rischio. Ne è autrice Sarah Legge, docente alla Charles Darwin University, che definisce la volpe una delle minacce più gravi per i mammiferi australiani. Sul fronte della tutela, intanto, nello Stato di Victoria sono entrati in vigore tre nuovi parchi nazionali. Proteggono oltre 250 miglia quadrate di foreste, habitat di petauri e gufi.",
