   "id": "zcba2a524",
   "sez": "tech",
   "titolo": "Bill Gates: mia figlia Phoebe mi ha aperto gli occhi sui problemi di internet",
   "orig": "Bill Gates says daughter Phoebe helped him understand the internet’s ‘big problem’",
   "lead": "Bill Gates ha raccontato che una conversazione con la figlia Phoebe gli ha fatto capire meglio il grande problema di internet. Phoebe gli ha parlato delle molestie online che ha subito in prima persona e della diffusione della disinformazione. Il racconto ha spinto il fondatore di Microsoft a rivedere le sue idee sulla responsabilità delle piattaforme. Gates ha ammesso che contrastare le notizie false diventa sempre più difficile, soprattutto con l'intelligenza artificiale. Ha anche riconosciuto che i danni di una falsità possono diventare irreparabili prima che arrivi una smentita. Lo riferisce Times of India.",
   "more": [
    "Bill Gates ha fondato Microsoft insieme a Paul Allen ed è stato a lungo tra gli uomini più ricchi del mondo. Oggi è conosciuto soprattutto per l'attività filantropica della sua fondazione, impegnata nella salute globale e nella lotta alla povertà."
   ],
