   "titolo": "Kazakistan, il corridoio Nord-Sud può diventare un'occasione economica?",
   "orig": "Can Kazakhstan Turn North-South Transit Into Economic Gains?",
   "lead": "Il Kazakistan scommette sul corridoio di trasporto Nord-Sud per aprire nuovi mercati all'export e diversificare le rotte commerciali. L'obiettivo è anche rafforzare il proprio ruolo di snodo di transito nella regione. Secondo alcuni esperti kazaki, però, sfruttare queste opportunità richiederà infrastrutture migliori e tariffe competitive. Servirà inoltre un coordinamento più stretto tra i Paesi coinvolti nel progetto. Il corridoio è tornato di recente al centro dell'attenzione. Lo riferisce The Astana Times.",
   "more": [
    "Il Kazakistan è il più grande Paese dell'Asia centrale e non ha sbocco sul mare aperto. Per questo i corridoi di trasporto terrestri e ferroviari sono strategici per collegarlo ai mercati di Russia, Cina, Iran e Golfo Persico."
   ],
