   "id": "z2412f670",
   "sez": "sport",
   "titolo": "Next Generation 2026 del Guardian: c'è anche un giovane senegalese",
   "orig": "Classement The Guardian « Next Generation 2026 » : Un Sénégalais parmi les 60 meilleurs jeunes talents de la planète",
   "lead": "Come ogni anno, il quotidiano britannico The Guardian ha pubblicato la classifica «Next Generation». La lista raccoglie i 60 giovani calciatori più promettenti al mondo nati nel 2009. Nell'edizione 2026 compare anche un talento senegalese, una presenza che in Senegal viene accolta come motivo di orgoglio per il calcio nazionale. Lo riferisce Seneweb.",
   "more": [
    "La lista «Next Generation» del Guardian è un appuntamento seguito da tifosi e osservatori. Segnala ogni anno giovanissimi calciatori considerati promettenti, alcuni dei quali sono poi diventati campioni affermati."
   ],
