   "id": "z8965387f",
   "sez": "mondo",
   "titolo": "Leone XIV chiede di proteggere il commercio di cereali minacciato dalla guerra in Ucraina",
   "orig": "León XIV urge a asegurar el comercio de cereales amenazado por la guerra en Ucrania",
   "lead": "Papa Leone XIV ha chiesto di mettere al sicuro il commercio dei cereali, minacciato dalla guerra in Ucraina. Il suo appello richiama le conseguenze del conflitto ben oltre i confini dei Paesi coinvolti. La guerra ha effetti anche in America Latina. In Perù un secondo presunto reclutatore di cittadini peruani destinati a combattere per la Russia è stato posto in custodia cautelare per 14 meseeee.",
   "more": [
    "L'Ucraina è uno dei maggiori esportatori mondiali di grano e altri cereali. Le sue spedizioni sono decisive per la sicurezza alimentare di molti Paesi, soprattutto in Africa e Medio Oriente. Il conflitto con la Russia ha più volte ostacolato le rotte del Mar Nero."
   ],
