   "id": "zc67cc912",
   "sez": "italia",
   "titolo": "Campo largo, Schlein: «Con un nome moderato non si vince»",
   "orig": "Schlein:si vince a centro? Sempre perso",
   "lead": "I cinque leader del campo largo del centrosinistra si sono presentati insieme. La segretaria del Pd Elly Schlein ha respinto l'idea che le elezioni si vincano al centro: con questa strategia, ha detto, si è sempre perso, e non basta un candidato moderato. Ha poi aggiunto che da quando guida il partito hanno cercato di commissariarla o di farla fuori, ma lei è ancora al suo posto. Giuseppe Conte ha annunciato che il programma comune sarà chiuso entro quindici giorni.",
   "more": [
    "Il «campo largo» è l'alleanza di centrosinistra che riunisce il Partito democratico, il Movimento 5 Stelle e altre forze progressiste. Il nodo principale riguarda la scelta della linea politica e della leadership in vista delle elezioni."
   ],
