   "id": "zb8284a05",
   "sez": "mondo",
   "titolo": "Il Papa nella Giornata contro la pena di morte: «È inammissibile»",
   "orig": "Papa: \"Pena capitale inammissibile\"",
   "lead": "In occasione della Giornata mondiale contro la pena di morte, il Papa ha pubblicato un messaggio sul social X. Ha ribadito che la pena capitale è inammissibile, perché attenta all'inviolabilità e alla dignità della persona. Secondo il Pontefice, il bene comune si può tutelare e la giustizia si può garantire anche senza ricorrere alle esecuzioni. Il messaggio conferma una posizione già consolidata della Chiesa cattolica.",
   "more": [
    "La Chiesa cattolica ha modificato il proprio Catechismo durante il pontificato di Francesco per definire la pena di morte inammissibile in ogni circostanza. La Giornata mondiale contro la pena di morte è promossa da organizzazioni impegnate per la sua abolizione."
   ],
