   "id": "z43132f4c",
   "sez": "mondo",
   "titolo": "Praga, sindaci e indipendenti primi alle comunali: arretrano i Pirati",
   "orig": "Mayors and Independents come first in Prague elections",
   "lead": "Il partito di opposizione Sindaci e indipendenti, noto con la sigla STAN, ha vinto le elezioni comunali di Praga con oltre il 23% dei voti. Quattro anni fa si era fermato al 7,8%. Guidata dal vicesindaco della capitale Petr Hlaváček, la formazione ha registrato la crescita più forte tra i principali gruppi politici in corsa. Arretra invece il Partito pirata. La notizia è riportata da Radio Prague International e Prague Morning.",
   "more": [
    "STAN è un movimento politico ceco nato dall'esperienza di amministratori locali e sindaci, di orientamento centrista e liberale. Il Partito pirata ceco, nato sui temi della trasparenza e dei diritti digitali, ha avuto un ruolo importante nella politica della capitale."
   ],
