   "id": "z94be457b",
   "sez": "sport",
   "titolo": "Baseball coreano, la corsa al terzo posto nei playoff KBO si decide all'ultima giornata",
   "orig": "Battle for 3rd seed in KBO postseason comes down to regular-season finale",
   "lead": "In Corea del Sud la lunga sfida per conquistare la terza testa di serie nella postseason del baseball professionistico KBO si risolverà nell'ultimo incontro di stagione regolare tra le due squadre in lizza. I Kia Tigers hanno sprecato domenica l'occasione di assicurarsi il terzo posto davanti al proprio pubblico, perdendo 4-1 contro i Lotte Giants al Gwangju-Kia Champions Field, nella città sudoccidentale di Gwangju. Una vittoria avrebbe chiuso i conti. Così il verdetto è rinviato allo scontro finale, che stabilirà chi partirà da una posizione più favorevole nel tabellone degli spareggi.",
   "more": [
    "La KBO League è il principale campionato professionistico di baseball della Corea del Sud, uno degli sport più seguiti nel Paese. Al termine della stagione regolare le squadre meglio classificate accedono a una fase a eliminazione in cui le posizioni più alte garantiscono vantaggi, come il fattore campo o l'accesso diretto ai turni successivi."
   ],
