   "id": "z1fe22dbf",
   "sez": "sport",
   "titolo": "Hong Kong Cyclothon, nuovo percorso tra elogi e proteste",
   "orig": "Riders praise new route for annual cyclothon",
   "lead": "Domenica a Hong Kong si è svolto il Cyclothon, che quest'anno ha spostato partenza e arrivo nel West Kowloon Cultural District e allungato la pedalata non competitiva da 50 a 56 chilometri, su un tracciato con cinque gallerie e tre ponti che include il Central Kowloon Bypass tra Yau Ma Tei e Kai Tak, attraversando sei distretti. C'era anche un percorso più corto di 32 chilometri. Diversi ciclisti hanno lodato la novità, utile secondo loro al turismo sportivo. Altri partecipanti invece hanno denunciato caos e confusione, in particolare per la chiusura imprevista del ponte di Ting Kau durante il giro da 32 chilometri e per gli ingorghi.",
   "more": [
    "Il Cyclothon è una manifestazione ciclistica annuale di Hong Kong che consente a migliaia di appassionati di pedalare su strade e infrastrutture normalmente riservate al traffico automobilistico, come tunnel, viadotti e ponti, affiancando le prove amatoriali a gare professionistiche."
   ],
