   "id": "zec81c492",
   "sez": "mondo",
   "titolo": "Filippine, i contratti della società di Sara Duterte con il Comune di Davao e lo scontro con Marcos",
   "orig": "[Inside the Newsroom] How Rappler uncovered Sara Duterte’s company contracts with Davao City Hall",
   "lead": "Nelle Filippine Rappler racconta come la sua redazione ha scoperto i contratti per la fornitura di cibo tra Gencorp, società legata alla vicepresidente Sara Duterte, e il Comune di Davao, sostenendo che i conflitti di interesse già emersi negli appalti per le infrastrutture possano riguardare anche altri settori e nascondersi nei registri degli acquisti pubblici. Intanto domenica, durante un'intervista a Singapore, il presidente Ferdinand Marcos Jr. ha liquidato come «fake news» l'accusa di Duterte secondo cui il suo governo sarebbe dietro una campagna per screditarla, sfidandola a presentare prove a sostegno delle sue affermazioni.",
   "more": [
    "Sara Duterte, figlia dell'ex presidente Rodrigo Duterte, è stata sindaca di Davao prima di diventare vicepresidente delle Filippine. L'alleanza politica con Ferdinand Marcos Jr. si è poi trasformata in un aperto conflitto, che segna profondamente la vita politica del Paese."
   ],
