   "id": "z552ae57f",
   "sez": "cultura",
   "titolo": "In un borgo del Cosentino si parla ancora un'antica lingua occitana",
   "orig": "In Calabria c’è un borgo dove il tempo si è fermato: a posto dell’italiano, si parla un dialetto vecchio di 800 anni",
   "lead": "In provincia di Cosenza, in Calabria, esiste un borgo che costituisce un'isola linguistica occitana in Italia: qui, al posto dell'italiano, gli abitanti parlano un idioma che ha circa 800 anni. La sua presenza è legata alla storia del culto valdese, una vicenda che secondo la testata merita di essere conosciuta da chi visita la regione o si interessa alle minoranze linguistiche del Paese. Il racconto presenta il paese come un luogo in cui il tempo sembra essersi fermato, custode di tradizioni lontane dal resto del territorio. Lo riferisce Turisti per Caso.",
   "more": [
    "L'occitano è una lingua romanza diffusa storicamente nel sud della Francia e in alcune valli del Piemonte. I valdesi sono una comunità cristiana nata nel Medioevo e a lungo perseguitata; alcuni loro gruppi si stabilirono in Calabria, dove l'eredità linguistica è sopravvissuta come minoranza tutelata."
   ],
