   "id": "z5f8e1135",
   "sez": "cultura",
   "titolo": "DC Comics annuncia Absolute Justice, primo incontro tra gli eroi dell'Universo Absolute",
   "orig": "DC Comics annuncia Absolute Justice, che riunirà per la prima volta gli eroi dell’Universo Absolute",
   "lead": "La casa editrice statunitense DC Comics ha annunciato Absolute Justice, una miniserie a fumetti in cinque numeri che per la prima volta riunirà gli eroi del cosiddetto Universo Absolute, la linea narrativa che reinterpreta i suoi personaggi più noti. La serie sarà scritta da Jason Aaron e disegnata da Juan Ferreyra, e metterà al centro della storia Martian Manhunter. L'annuncio segna un passaggio importante per questa linea editoriale, finora sviluppata attraverso testate dedicate ai singoli personaggi. Lo riferisce Fumettologica.",
   "more": [
    "DC Comics è uno dei due grandi editori del fumetto di supereroi americano, casa di Superman, Batman e Wonder Woman. Martian Manhunter è un supereroe proveniente da Marte, storico membro della Justice League, noto per i poteri telepatici e la capacità di cambiare aspetto."
   ],
