   "id": "z3e898e09",
   "sez": "mondo",
   "titolo": "Portogallo, il sindacato UGT scende a 430 mila iscritti",
   "orig": "UGT. Central sindical tem 430 mil trabalhadores filiados, menos cinco mil face a 2022",
   "lead": "In Portogallo la centrale sindacale UGT conta oggi circa 430 mila lavoratori iscritti, cinquemila in meno rispetto al 2022. I dati sono stati forniti all'agenzia Lusa da una fonte ufficiale dell'organizzazione e compaiono nel rapporto di attività del segretariato nazionale. Secondo lo stesso documento, alla UGT aderiscono 50 associazioni sindacali, 27 in meno di quattro anni fa, oltre a sette federazioni e 20 unioni. Le cifre fotografano un calo sia degli iscritti sia delle strutture affiliate nell'arco di quattro anni.",
   "more": [
    "La UGT, Unione generale dei lavoratori, è una delle due principali confederazioni sindacali portoghesi insieme alla CGTP. È tradizionalmente considerata più moderata e orientata alla concertazione con governo e imprenditori."
   ],
