   "sez": "mondo",
   "titolo": "Germania, Seehofer accusa Merz di aver tradito le promesse elettorali",
   "orig": "Seehofer kritisiert Merz vor CDU-Präsidiumsklausur",
   "lead": "In Germania l'ex leader della Csu Horst Seehofer ha criticato duramente il cancelliere Friedrich Merz, accusandolo di aver rotto le promesse elettorali e di soffrire di una «massiccia perdita di credibilità». L'attacco arriva alla vigilia della riunione a porte chiuse della presidenza della Cdu, convocata da Merz per domenica per discutere le conseguenze delle recenti sconfitte elettorali del partito. Le parole di Seehofer aggiungono tensione nel campo conservatore in un momento delicato per il governo.",
   "more": [
    "La Cdu e la sua alleata bavarese Csu formano l'Unione, il blocco conservatore tedesco. Horst Seehofer ha guidato la Csu, è stato presidente della Baviera e ministro dell'Interno federale. Friedrich Merz guida la Cdu ed è il cancelliere tedesco."
   ],
