   "sez": "musica",
   "titolo": "Paolo Jannacci torna con l'album «Scimmie ovunque»",
   "orig": "Torna Paolo Jannacci: 'Ridere dei guai per affrontare il dolore'",
   "lead": "Il cantautore milanese Paolo Jannacci pubblica il 16 ottobre il nuovo album «Scimmie ovunque», che racconta le fragilità e le contraddizioni del presente alternando temi duri e momenti di leggerezza. L'idea di fondo, spiega l'artista, è ridere dei guai per affrontare il dolore. Nel disco c'è anche una canzone dedicata al padre Enzo. Jannacci dice di credere nel riscatto umano, ma di non vederlo questa volta, e confessa che gli piacerebbe partecipare al Festival di Sanremo.",
   "more": [
    "Paolo Jannacci è musicista, pianista e cantautore, figlio di Enzo Jannacci, uno dei protagonisti della canzone d'autore milanese, celebre per l'umorismo surreale e la sensibilità verso gli ultimi. Paolo ha a lungo collaborato con il padre prima di affermarsi con progetti propri."
   ],
