   "id": "z520b68d7",
   "sez": "tech",
   "titolo": "Occhiali smart, dalla Gran Bretagna alla Norvegia cresce la stagione dei divieti",
   "orig": "Dalla Gran Bretagna alla Norvegia, gli occhiali smart nuova frontiera dei divieti tecnologici",
   "lead": "Dalla Gran Bretagna alla Norvegia gli occhiali intelligenti stanno diventando il nuovo bersaglio dei divieti tecnologici in Europa. Il problema principale riguarda il consenso delle persone negli spazi pubblici, che possono essere riprese o registrate senza accorgersene da chi indossa questi dispositivi. Un esperto interpellato sul tema sostiene che le regole esistenti vadano aggiornate per tenere conto di queste nuove tecnologie, ancora poco disciplinate. Lo riferisce ANSA.",
   "more": [
    "Gli occhiali smart sono dispositivi indossabili che integrano fotocamere, microfoni e talvolta assistenti basati sull'intelligenza artificiale. Permettono di scattare foto, girare video o ricevere informazioni senza usare lo smartphone, sollevando interrogativi sulla privacy di chi viene ripreso."
   ],
