   "id": "z80aceae4",
   "sez": "cultura",
   "titolo": "Le cabine telefoniche rinascono come biblioteche e chioschi del caffè",
   "orig": "Ultima chiamata per le cabine telefoniche: diventano biblioteche o chioschi per il caffè",
   "lead": "Le vecchie cabine telefoniche, ormai superate dai cellulari, trovano una seconda vita come piccole biblioteche o chioschi per il caffè. In Scozia gli abitanti si sono organizzati per riutilizzare la postazione del loro paese ed evitarne la dismissione, mentre altri appassionati sono pronti a tutto pur di salvare queste strutture legate all'epoca del «gettone». Si tratta di iniziative dal basso che trasformano oggetti destinati a scomparire in nuovi punti di ritrovo per le comunità. Lo riferisce la Repubblica.",
   "more": [
    "Le cabine telefoniche pubbliche sono state per decenni l'unico modo per telefonare fuori casa. Nel Regno Unito quelle rosse sono diventate un simbolo nazionale, e molte comunità le hanno adottate trasformandole in spazi per lo scambio di libri o per ospitare defibrillatori."
   ],
