   "id": "ze4d45cf4",
   "sez": "italia",
   "titolo": "Ranucci dopo lo stop a Report: «Voglio fare il giornalista»",
   "orig": "Ranucci dopo lo stop a Report: “Voglio fare il giornalista, ma sono a disposizione della società”",
   "lead": "Dopo il no al reintegro alla guida di Report, Sigfrido Ranucci dichiara di voler continuare a fare il giornalista e di restare a disposizione della Rai, mentre prepara con i suoi avvocati le prossime mosse contro l'azienda. Sullo sfondo ci sono la sospensione disciplinare, la sua testimonianza sull'attentato subito e il caso Lavitola. La redazione del programma assicura che nessuno lo ha sfiduciato, mentre la giudice parla di pressioni del governo sui vertici della tv pubblica. Intanto esce un libro di Marco Milioni e Gianluca Prestigiacomo che ricostruisce il caso.",
   "more": [
    "Report è il programma d'inchiesta di Rai 3, noto per le indagini su politica, economia e potere. Sigfrido Ranucci ne è stato a lungo il conduttore ed è diventato un simbolo del giornalismo investigativo in Italia, anche per le minacce ricevute."
   ],
