   "id": "z737b972b",
   "sez": "italia",
   "titolo": "Scampia, le prime tre palazzine nuove al posto delle Vele",
   "orig": "Goodbye Gomorrah: new homes rise in place of Scampia’s Vele",
   "lead": "A Napoli, nel quartiere di Scampia, sono pronte le prime tre palazzine costruite dove sorgeva una parte delle storiche e discusse Vele, i grandi complessi di edilizia popolare ormai degradati. Le nuove abitazioni sono descritte come «verdi» e segnano il completamento della prima fase della riqualificazione dell'area. Il progetto punta a cambiare il volto di un luogo diventato tristemente famoso anche grazie al racconto della camorra fatto da Roberto Saviano in Gomorra.",
   "more": [
    "Le Vele di Scampia sono enormi edifici residenziali costruiti nella periferia nord di Napoli, con una caratteristica forma triangolare. Nati come progetto di edilizia popolare innovativo, sono diventati simbolo di degrado e criminalità organizzata, e da anni sono oggetto di abbattimenti e piani di rinascita."
   ],
