   "id": "zc4752bb6",
   "sez": "mondo",
   "titolo": "La trattativa tra Casa Bianca e Cremlino e il rischio per gli alleati europei",
   "orig": "La trattativa con Putin per ottenere la tregua sulla pelle degli alleati",
   "lead": "Un'analisi della Repubblica esamina l'intesa economica tra la Casa Bianca e il Cremlino, che punterebbe a ottenere una tregua offrendo al presidente russo Vladimir Putin una via d'uscita. Secondo la testata, però, il prezzo dell'accordo rischia di essere pagato dagli alleati degli Stati Uniti: in gioco, scrive il giornale, ci sono le democrazie europee, che vedrebbero indebolita la propria posizione di fronte a Mosca. Lo riferisce la Repubblica.",
   "more": [
    "Dall'inizio della guerra in Ucraina, Stati Uniti ed Europa hanno coordinato sanzioni e aiuti a Kiev. Negli ultimi tempi Washington ha cercato un dialogo diretto con Mosca, suscitando timori nelle capitali europee di essere escluse da decisioni sulla sicurezza del continente."
   ],
