   "id": "z87b704e9",
   "sez": "mondo",
   "titolo": "Dal diesel agli assegni, le mosse di Trump per recuperare consensi prima del midterm",
   "orig": "Dal diesel agli assegni: così Trump vuole comprare il voto degli americani",
   "lead": "Negli Stati Uniti il presidente Donald Trump è in calo di consensi a meno di un mese dalle elezioni di metà mandato. Per rimontare, secondo un'analisi della Repubblica, la Casa Bianca punta su misure capaci di incidere direttamente sulle tasche degli elettori, dal prezzo del diesel agli assegni, fino ai rimborsi sanitari tornati di attualità. Il giornale descrive questa strategia come un tentativo di «comprare» il voto degli americani. Lo riferisce la Repubblica.",
   "more": [
    "Le elezioni di midterm si tengono a metà del mandato presidenziale e rinnovano tutta la Camera dei rappresentanti e circa un terzo del Senato. Sono considerate un referendum sull'operato del presidente e spesso penalizzano il partito al governo."
   ],
