   "id": "zaf1ee3b3",
   "sez": "italia",
   "titolo": "Comunali, scontro Lega-Forza Italia su Milano e Meloni chiama Tajani",
   "orig": "Meloni irritata chiama Tajani: “Basta spaccare il centrodestra sui nomi per le Comunali”",
   "lead": "Il centrodestra si divide sulla scelta dei candidati per le elezioni comunali, a partire da Milano. Matteo Salvini insiste sull'eurodeputata Silvia Sardone per il dopo Sala e rilancia le primarie, mentre il segretario lombardo di Forza Italia, Alessandro Sorte, provoca: se la Lega vuole una partita identitaria può correre da sola. Gli azzurri replicano che allora le primarie andrebbero fatte ovunque, con La Russa a mediare. Irritata, la premier Giorgia Meloni ha chiamato Tajani chiedendo di smettere di spaccare la coalizione e fissando la linea: i nomi dopo il congresso della Lega. Fastidio anche per gli elogi di Occhiuto a Renzi.",
   "more": [
    "Il centrodestra italiano è formato principalmente da Fratelli d'Italia, Lega e Forza Italia. A Milano, governata dal centrosinistra con Giuseppe Sala, la scelta del candidato sindaco è un banco di prova per gli equilibri della coalizione."
   ],
