   "id": "zadd05608",
   "sez": "economia",
   "titolo": "Btp, nuova asta il 13 ottobre: tre titoli a medio-lungo termine",
   "orig": "Btp, nuova asta il 13 ottobre: i titoli da osservare, come partecipare e quali rendimenti aspettarsi. La guida",
   "lead": "Il Ministero dell'Economia e delle Finanze torna sul mercato il 13 ottobre con una nuova asta di Btp a medio-lungo termine, proponendo tre strumenti agli investitori. Il Messaggero offre una guida all'appuntamento con i titoli di Stato italiani, spiegando quali emissioni tenere d'occhio, come partecipare all'asta e quali rendimenti ci si può attendere. L'operazione rientra nel calendario ordinario con cui il Tesoro finanzia il debito pubblico. Lo riferisce Il Messaggero.",
   "more": [
    "I Btp, Buoni del Tesoro poliennali, sono titoli di Stato italiani a medio e lungo termine che pagano cedole periodiche. Il Tesoro li colloca tramite aste a cui partecipano gli intermediari finanziari; i risparmiatori possono acquistarli attraverso banche o piattaforme di trading."
   ],
