   "id": "zc1f4733e",
   "sez": "sport",
   "titolo": "L'Inter travolge il Parma 3-0 e vola in testa alla Serie A",
   "orig": "Inter-Parma, 3-0: le pagelle: Sucic (7,5) decimo marcatore in sei giornate, Thuram (7,5) cinico, Calhanoglu (7) cecchino dal dischetto",
   "lead": "A San Siro l'Inter ha battuto 3-0 il Parma e, dopo sei giornate, è salita da sola in vetta alla classifica con 16 punti, in attesa di Roma e Lazio. Ai nerazzurri sono bastati trenta minuti: hanno segnato Sucic, decimo marcatore diverso in sei turni, Calhanoglu su rigore e Thuram, poi la ripresa è stata pura gestione. Polemiche invece tra i tifosi sui social contro Dazn e Sky, perché la regia televisiva non ha mostrato in diretta il gol del vantaggio di Sucic al 13°.",
   "more": [
    "L'Inter è una delle squadre più titolate del calcio italiano e gioca le gare casalinghe a San Siro, lo stadio di Milano che condivide con il Milan. Il Parma, club emiliano con un passato di successi europei, è tornato di recente in Serie A."
   ],
