   "id": "z91fd469b",
   "sez": "cultura",
   "titolo": "Arazzo di Bayeux a Londra, appassionati alla rievocazione della battaglia di Hastings",
   "orig": "Bayeux Tapestry's London tour spurs enthusiasts to Battle of Hastings reenactment",
   "lead": "Nel Regno Unito una rievocazione storica della battaglia di Hastings, combattuta quasi mille anni fa, sta attirando folle di appassionati. A dare nuova spinta all'interesse è il trasferimento a Londra dell'arazzo di Bayeux, la celebre opera che racconta quegli avvenimenti. La presenza dell'arazzo nella capitale britannica ha incoraggiato molte persone a partecipare o ad assistere alla ricostruzione della battaglia, rivivendo un momento chiave della storia inglese. Lo riferisce NPR.",
   "more": [
    "La battaglia di Hastings, nel 1066, segnò la conquista dell'Inghilterra da parte dei Normanni guidati da Guglielmo il Conquistatore. L'arazzo di Bayeux è un lunghissimo ricamo medievale, conservato in Francia, che racconta per immagini quegli eventi. Le rievocazioni storiche sono spettacoli in cui appassionati in costume ricostruiscono battaglie e scene del passato."
   ],
