   "id": "z32267d3f",
   "sez": "cultura",
   "titolo": "La Cina cerca di limitare la presenza culturale di Taiwan nel mondo?",
   "orig": "Is China seeking to restrict Taiwan's cultural presence?",
   "lead": "Deutsche Welle si chiede se Pechino stia cercando di ridurre la presenza culturale di Taiwan sulla scena internazionale. Dai concorsi dedicati al caffè fino ai premi letterari, la Cina sembra lavorare per limitare l'influenza culturale e politica dell'isola nel mondo. Secondo l'analisi, questo impegno tocca ambiti molto diversi tra loro, anche lontani dalla politica, e fa parte di una strategia più ampia nei rapporti tra Pechino e Taipei. Lo riferisce Deutsche Welle.",
   "more": [
    "Taiwan è un'isola dell'Asia orientale che si governa da sola, con proprie istituzioni democratiche. La Repubblica popolare cinese la considera parte del proprio territorio e cerca di ridurne il riconoscimento internazionale. Per questo anche la partecipazione di Taiwan a eventi sportivi, culturali o commerciali all'estero diventa spesso oggetto di tensioni diplomatiche."
   ],
