   "sez": "economia",
   "titolo": "Gli effetti della guerra in Iran sull'energia mondiale, spiegati con i grafici",
   "orig": "What the Iran war has done to the world’s energy supply, in charts",
   "lead": "Al Jazeera analizza con una serie di grafici le conseguenze della guerra in Iran sulle forniture di energia nel mondo. Il punto di partenza è un dato: i combustibili fossili producono l'81 per cento dell'energia globale. L'approfondimento esamina il ruolo che il Medio Oriente ha in questo sistema e che cosa accade quando le forniture provenienti dalla regione vengono interrotte, mostrando quanto il mondo dipenda ancora da petrolio e gas. Lo riferisce Al Jazeera.",
   "more": [
    "I combustibili fossili sono petrolio, gas naturale e carbone, formatisi in milioni di anni dai resti di organismi. Il Medio Oriente possiede alcune delle più grandi riserve di petrolio e gas del pianeta, e molte rotte marittime della regione sono fondamentali per il loro trasporto. Per questo i conflitti nell'area possono far salire i prezzi dell'energia ovunque."
   ],
