   "sez": "adolescenti",
   "titolo": "Scuole pubbliche Usa: cinque cose dai dati sui diritti civili",
   "orig": "5 things civil rights data says about public schools",
   "lead": "Negli Stati Uniti la raccolta federale di dati sui diritti civili nelle scuole offre nuove informazioni sull'istruzione pubblica. Per la prima volta dopo decenni, questi dati descrivono anche il personale insegnante, cioè chi lavora nelle classi americane. Allo stesso tempo, ricordano che le differenze legate all'origine etnica degli studenti sono ancora molto forti nelle scuole pubbliche del Paese. NPR ha riassunto i risultati in cinque punti principali. Lo riferisce NPR – Istruzione.",
   "more": [
    "La Civil Rights Data Collection è un'indagine del governo federale degli Stati Uniti che raccoglie informazioni dalle scuole pubbliche, per controllare che tutti gli studenti abbiano le stesse opportunità. I dati riguardano, per esempio, l'accesso ai corsi, le punizioni disciplinari e le risorse disponibili, divisi per gruppi di studenti."
   ],
