   "id": "z364c23b1",
   "sez": "adolescenti",
   "titolo": "Scoperto un animale preistorico simile a una lontra che nuotava al tempo dei dinosauri",
   "orig": "Meet the prehistoric otter-like animal that swam alongside dinosaurs",
   "lead": "Un gruppo di scienziati ha identificato una nuova specie di animale preistorico che, per aspetto e abitudini, ricorda una lontra. La creatura viveva circa 165 milioni di anni fa e nuotava nelle acque di laghi e fiumi, in un'epoca in cui sulla Terra dominavano i dinosauri. La scoperta aggiunge un nuovo tassello alla conoscenza degli ecosistemi d'acqua dolce di quel lontano periodo e degli animali che li abitavano accanto ai grandi rettili. Lo riferisce BBC Newsround.",
   "more": [
    "Le specie preistoriche vengono descritte dai paleontologi studiando fossili come ossa e denti. Il confronto con animali attuali, come la lontra, serve a far capire lo stile di vita: un corpo adatto al nuoto suggerisce che l'animale cacciasse o si muovesse soprattutto in acqua. Nell'epoca dei dinosauri vivevano anche molti piccoli animali meno conosciuti."
   ],
