   "id": "z8752a1c3",
   "sez": "musica",
   "titolo": "Alessio Creatura, «Libero dalle cose»: quindici anni senza smarrire la strada",
   "orig": "Alessio Creatura - Libero dalle cose: quindici anni senza smarrire la strada",
   "lead": "In occasione dell'uscita del suo nuovo lavoro, «Libero dalle cose», il cantautore di origine abruzzese Alessio Creatura è stato intervistato in esclusiva da OndaRock. Il titolo dell'articolo richiama i quindici anni di percorso artistico del musicista, presentati come un cammino coerente in cui non ha perso la propria direzione. L'intervista diventa così l'occasione per ripercorrere la sua carriera e raccontare il disco appena pubblicato. Lo riferisce OndaRock.",
   "more": [
    "OndaRock è una rivista musicale online italiana che si occupa di rock, cantautorato ed elettronica, con recensioni, monografie e interviste. Il cantautorato è una tradizione molto radicata nella musica italiana, in cui l'autore scrive e interpreta le proprie canzoni."
   ],
