  "z7ca2ce6f": "La Repubblica adotta un tono nostalgico, celebrando il valore storico e affettivo dello stadio.",
  "z6d3e0ad6": "Il Sole 24 Ore riporta l'appello presidenziale alla prevenzione come messaggio istituzionale.",
  "z951cbc7e": "Il Sole 24 Ore collega l'andamento dei prezzi alle scelte di politica fiscale del governo.",
  "z63b18301": "Il Sole 24 Ore mette in risalto il dato statistico sulla diffusione dello svapo tra gli adolescenti.",
  "zc992c5b7": "Positive News valorizza il ruolo delle donne come protagoniste di un cambiamento nei modelli di conservazione.",
  "z429b5a45": "Good News Network evidenzia il ruolo delle comunità locali come elemento decisivo più del finanziamento economico.",
  "z2d8ffa16": "Good News Network sottolinea la portata della spedizione e la varietà dei reperti ritrovati.",
  "zae3dcc53": "Il Financial Times presenta il proprio strumento di monitoraggio come chiave di lettura del voto.",
  "ze10c56e5": "The Washington Post riporta la reazione critica del premier israeliano al film, accolto invece positivamente dal pubblico del festival.",
  "ze4dcef04": "Egypt Independent riporta le dichiarazioni critiche di Trump durante un evento elettorale negli Stati Uniti.",
  "z832840f2": "Citizen Digital riporta i numeri ufficiali dell'operazione di tracciamento come segnale di risposta attiva.",
  "zdf589eb9": "Citizen Digital sottolinea la forza del movimento rugbistico keniano, capace di dominare con due squadre diverse.",
  "z26e88e42": "Citizen Digital si concentra sulle occasioni sprecate dalla Roma nel primo tempo."
